import io, struct, zstandard as zstd
HEADER=('type,id,revision,published,op,lease,event,probe,target,responder,'
        'result,service,attempt,payload\r\n')
data=HEADER.encode()
def frame(descriptor, payload=data):
    bh=(len(payload)<<3)|1   # raw block, last
    return b'\x28\xb5\x2f\xfd'+bytes([descriptor])+struct.pack('<I',bh)[:3]+payload
from classify_responses import complete_frames
for d in (0x00,0x88,0x90,0xF8):
    f=frame(d)
    try:
        print(hex(d),'walk',complete_frames(f))
    except Exception as e: print(hex(d),'walk ERR',type(e).__name__,e)
    try:
        out=zstd.ZstdDecompressor().stream_reader(io.BytesIO(f),read_across_frames=True).read()
        print('   decomp',len(out))
    except Exception as e: print('   decomp ERR',type(e).__name__,e)
PYEOF
